2850: static int ice_ptp_register_auxbus_driver(struct ice_pf *pf)
2851: {
2852: 	struct auxiliary_driver *aux_driver;
2853: 	struct ice_ptp *ptp;
2854: 	struct device *dev;
2855: 	char *name;
2856: 	int err;
2857: 
2858: 	ptp = &pf->ptp;
2859: 	dev = ice_pf_to_dev(pf);
2860: 	aux_driver = &ptp->ports_owner.aux_driver;
2861: 	INIT_LIST_HEAD(&ptp->ports_owner.ports);
2862: 	mutex_init(&ptp->ports_owner.lock);
2863: 	name = devm_kasprintf(dev, GFP_KERNEL, "ptp_aux_dev_%u_%u_clk%u",
2864: 			      pf->pdev->bus->number, PCI_SLOT(pf->pdev->devfn),
2865: 			      ice_get_ptp_src_clock_index(&pf->hw));
2866: 
2867: 	aux_driver->name = name;
2868: 	aux_driver->shutdown = ice_ptp_auxbus_shutdown;
2869: 	aux_driver->suspend = ice_ptp_auxbus_suspend;
2870: 	aux_driver->remove = ice_ptp_auxbus_remove;
2871: 	aux_driver->resume = ice_ptp_auxbus_resume;
2872: 	aux_driver->probe = ice_ptp_auxbus_probe;
2873: 	aux_driver->id_table = ice_ptp_auxbus_create_id_table(pf, name);
2874: 	if (!aux_driver->id_table)
2875: 		return -ENOMEM;
2876: 
2877: 	err = auxiliary_driver_register(aux_driver);
2878: 	if (err) {
2879: 		devm_kfree(dev, aux_driver->id_table);
2880: 		dev_err(dev, "Failed registering aux_driver, name <%s>\n",
2881: 			name);
2882: 	}
2883: 
2884: 	return err;
2885: }

