3110: 			      pf->pdev->bus->number, PCI_SLOT(pf->pdev->devfn),
3111: 			      ice_get_ptp_src_clock_index(&pf->hw));
3112: 
3113: 	aux_dev->name = name;
3114: 	aux_dev->id = id;
3115: 	aux_dev->dev.release = ice_ptp_release_auxbus_device;
